window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5b4bcd38bd29f4a3"]={"versions": [{"id": "FIG-5b4bcd38bd29f4a3", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des funktionalen Kontrollflusses der Funktion <code>E2E_P04mProtect()</code> innerhalb der AUTOSAR E2E-Bibliothek (E2E Profile 4m Protect). Das Diagramm beschreibt die senderseitige Absicherung von Nutzdaten mit flexiblen Metadaten (SourceID, MessageType, MessageResult) im Rahmen des AUTOSAR End-to-End-Kommunikationsschutzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionsschnittstelle:</strong> <code>E2E_P04mProtect(Config, State, SourceID, MessageType, MessageResult, Data, Length)</code></li>\n<li><strong>Parameter & Entitäten:</strong></li>\n<li><code>Config</code>: Konfigurationsstruktur des E2E-Profils 4m.</li>\n<li><code>State</code>: Zustandsstruktur des Senders (enthält u. a. den Counter).</li>\n<li><code>SourceID</code>: Quellidentifikator der Nachricht.</li>\n<li><code>MessageType</code>: Typkennung der Nachricht.</li>\n<li><code>MessageResult</code>: Statusergebnis der Nachricht.</li>\n<li><code>Data</code>: Zeiger auf den zu schützenden Nutzdatenpuffer.</li>\n<li><code>Length</code>: Länge der Nutzdaten bzw. der Gesamtnachricht.</li>\n<li><strong>Unteraktivitäten (Sub-Activities / Actions):</strong></li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Write SourceID</code></li>\n<li><code>Write Message Type</code></li>\n<li><code>Write Message Result</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li><strong>Kontrollknoten:</strong> Initialknoten, drei Activity-Final-Knoten (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet am Initialknoten beim Aufruf von <code>E2E_P04mProtect()</code>.</li>\n<li>Zunächst wird die Aktion <code>Verify inputs of the protect function</code> ausgeführt.</li>\n<li>Anhand der Eingangsparameter verzweigt der Kontrollfluss über Guard-Bedingungen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[null input]</code>: Verzweigung direkt zum linken Activity-Final-Knoten (<code>return</code>, Fehlerbehandlung bei Null-Zeigern).</li>\n<li><code>[wrong input]</code>: Verzweigung direkt zum rechten Activity-Final-Knoten (<code>return</code>, Fehlerbehandlung bei ungültigen Parameterwerten).</li>\n<li><code>[input ok]</code>: Fortsetzung des regulären Schutzablaufs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei erfolgreicher Verifikation (<code>[input ok]</code>) folgt eine strikt sequentielle Kette von Aktionen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Write SourceID</code></li>\n<li><code>Write Message Type</code></li>\n<li><code>Write Message Result</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Inkrementieren des Counters schließt der Kontrollfluss am mittleren Activity-Final-Knoten (<code>return</code>) ab.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist gemäß Anforderung <code>[PRS_E2E_00756]</code> normativ bindend für die softwareseitige Implementierung von <code>E2E_P04mProtect()</code>. Entwickler müssen sicherstellen, dass vor jeglicher Puffer- oder Zustandsmodifikation eine vollständige Validierung aller Zeiger- und Werteparameter erfolgt. Bei fehlerhafter Validierung darf weder der Counter inkrementiert noch in den Datenpuffer geschrieben werden. Im Erfolgsfall müssen Metadatenfelder (Length, Counter, DataID, SourceID, MessageType, MessageResult) und Prüfsumme (CRC) in der vorgegebenen Reihenfolge verarbeitet und serialisiert werden, bevor der Zustandscounter für nachfolgende Übertragungen aktualisiert wird.</p>"}, {"id": "FIG-1d2db49f03ec1b63", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des funktionalen Kontrollflusses der Funktion <code>E2E_P04mProtect()</code> innerhalb der AUTOSAR E2E-Bibliothek (E2E Profile 4m Protect). Das Diagramm beschreibt die senderseitige Absicherung von Nutzdaten mit flexiblen Metadaten (SourceID, MessageType, MessageResult) im Rahmen des AUTOSAR End-to-End-Kommunikationsschutzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Funktionsschnittstelle:</strong> <code>E2E_P04mProtect(Config, State, SourceID, MessageType, MessageResult, Data, Length)</code></li>\n<li><strong>Parameter & Entitäten:</strong></li>\n<li><code>Config</code>: Konfigurationsstruktur des E2E-Profils 4m.</li>\n<li><code>State</code>: Zustandsstruktur des Senders (enthält u. a. den Counter).</li>\n<li><code>SourceID</code>: Quellidentifikator der Nachricht.</li>\n<li><code>MessageType</code>: Typkennung der Nachricht.</li>\n<li><code>MessageResult</code>: Statusergebnis der Nachricht.</li>\n<li><code>Data</code>: Zeiger auf den zu schützenden Nutzdatenpuffer.</li>\n<li><code>Length</code>: Länge der Nutzdaten bzw. der Gesamtnachricht.</li>\n<li><strong>Unteraktivitäten (Sub-Activities / Actions):</strong></li>\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Write SourceID</code></li>\n<li><code>Write Message Type</code></li>\n<li><code>Write Message Result</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n<li><strong>Kontrollknoten:</strong> Initialknoten, drei Activity-Final-Knoten (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet am Initialknoten beim Aufruf von <code>E2E_P04mProtect()</code>.</li>\n<li>Zunächst wird die Aktion <code>Verify inputs of the protect function</code> ausgeführt.</li>\n<li>Anhand der Eingangsparameter verzweigt der Kontrollfluss über Guard-Bedingungen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[null input]</code>: Verzweigung direkt zum linken Activity-Final-Knoten (<code>return</code>, Fehlerbehandlung bei Null-Zeigern).</li>\n<li><code>[wrong input]</code>: Verzweigung direkt zum rechten Activity-Final-Knoten (<code>return</code>, Fehlerbehandlung bei ungültigen Parameterwerten).</li>\n<li><code>[input ok]</code>: Fortsetzung des regulären Schutzablaufs.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Bei erfolgreicher Verifikation (<code>[input ok]</code>) folgt eine strikt sequentielle Kette von Aktionen:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Write SourceID</code></li>\n<li><code>Write Message Type</code></li>\n<li><code>Write Message Result</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach Inkrementieren des Counters schließt der Kontrollfluss am mittleren Activity-Final-Knoten (<code>return</code>) ab.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist gemäß Anforderung <code>[PRS_E2E_00756]</code> normativ bindend für die softwareseitige Implementierung von <code>E2E_P04mProtect()</code>. Entwickler müssen sicherstellen, dass vor jeglicher Puffer- oder Zustandsmodifikation eine vollständige Validierung aller Zeiger- und Werteparameter erfolgt. Bei fehlerhafter Validierung darf weder der Counter inkrementiert noch in den Datenpuffer geschrieben werden. Im Erfolgsfall müssen Metadatenfelder (Length, Counter, DataID, SourceID, MessageType, MessageResult) und Prüfsumme (CRC) in der vorgegebenen Reihenfolge verarbeitet und serialisiert werden, bevor der Zustandscounter für nachfolgende Übertragungen aktualisiert wird.</p>"}], "trans": [{"from": "FIG-5b4bcd38bd29f4a3", "to": "FIG-1d2db49f03ec1b63", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
